package org.sleepwell.app;
import org.junit.Test;import java.util.*;import static org.junit.Assert.*;

public final class SpeakRuntimeTest {
 static float[] speech(){float[] scores=new float[521];scores[0]=.9f;return scores;}static float[] noise(){float[] scores=new float[521];scores[100]=.9f;return scores;}
 static final class Fake implements SpeakRuntime.Port {long time;boolean live=true,allowed=true,failQuiet,closeFailed,zero,modelFailed,immediate,inline,rejected;int quiet,resumed,opened,closed,models,modelClosed;Runnable ready,duringInfer;SpeakRuntime runtime;Deque<Runnable> worker=new ArrayDeque<>();List<String> effects=new ArrayList<>();public long now(){return time;}public boolean current(){return live;}public void check(){if(!allowed)throw new SecurityException();}public SpeakRuntime.Quiet quiet(Runnable ready){if(failQuiet)throw new IllegalStateException();quiet++;this.ready=ready;if(immediate)ready.run();return ()->{if(live)resumed++;effects.add("quiet-closed");};}public SpeakRuntime.Capture open(){opened++;effects.add("capture-open");return new SpeakRuntime.Capture(){public void start(){effects.add("capture-start");}public int read(short[] values){time+=64;return zero?0:values.length;}public void close(){closed++;effects.add("capture-close");if(closeFailed)throw new IllegalStateException();}};}public SoundAnalysisStream.Model model(){models++;if(modelFailed)throw new IllegalStateException();return new SoundAnalysisStream.Model(){public float[] infer(float[] values){assertEquals(15600,values.length);if(duringInfer!=null)duringInfer.run();return speech();}public void close(){modelClosed++;effects.add("model-close");}};}public void execute(Runnable work){if(rejected)throw new java.util.concurrent.RejectedExecutionException();if(inline)work.run();else worker.add(work);}public void idle(){time+=10;}public void changed(){}void run(){while(!worker.isEmpty())worker.remove().run();}}
 SpeakRuntime make(Fake f){return f.runtime=new SpeakRuntime(f);}
 @Test public void immediateQuietAndInlineWorkerStillOwnAndRestoreQuietToken(){Fake f=new Fake();f.immediate=true;f.inline=true;SpeakRuntime r=make(f);assertTrue(r.start());assertEquals(SpeakRuntime.State.DONE,r.state);assertEquals(1,f.closed);assertEquals(1,f.resumed);assertEquals(1,Collections.frequency(f.effects,"quiet-closed"));}
 @Test public void delayedQuietExecutorRejectionRestoresSoundWithoutCapture(){Fake f=new Fake();SpeakRuntime r=make(f);r.start();f.rejected=true;f.ready.run();assertEquals(SpeakRuntime.State.ERROR,r.state);assertTrue(r.released());assertEquals(0,f.opened);assertEquals(1,f.resumed);f.ready.run();assertEquals(1,f.resumed);}
 @Test public void unclaimedTicketExpiresAndCannotBeReplayed(){SpeakAdmission a=new SpeakAdmission(10);assertFalse(a.expired(5009));assertTrue(a.expired(5010));assertFalse(a.claim(5010));SpeakAdmission b=new SpeakAdmission(10);assertTrue(b.claim(11));assertFalse(b.claim(12));assertFalse(b.expired(6000));}
 @Test public void releasedServiceOwnerCanBeReplacedAndOldFinishCannotStopIt(){SpeakServiceSlot<Object> slot=new SpeakServiceSlot<>();Object old=new Object(),next=new Object();assertFalse(slot.occupied(o->false));slot.adopt(old,1);assertTrue(slot.occupied(o->false));assertFalse(slot.occupied(o->true));slot.adopt(next,2);assertFalse(slot.owns(old,1));assertFalse(slot.owns(next,1));assertTrue(slot.owns(next,2));}
 @Test public void twoProductionSpeechWindowsPassAndOtherSoundResetsWithoutAmplitudeLabels(){SpeakRule rule=new SpeakRule();assertFalse(rule.accept(speech()));assertFalse(rule.accept(noise()));assertFalse(rule.accept(speech()));assertTrue(rule.accept(speech()));assertFalse(rule.accept(speech()));}
 @Test public void noAllocationBeforeConfirmedQuietAndCompletionFollowsCaptureClose(){Fake f=new Fake();SpeakRuntime r=make(f);assertTrue(r.start());assertEquals(0,f.opened);assertEquals(0,f.models);assertEquals(SpeakRuntime.State.QUIETING,r.state);f.ready.run();assertEquals(0,f.opened);f.run();assertEquals(SpeakRuntime.State.DONE,r.state);assertTrue(r.released());assertEquals(1,f.opened);assertEquals(1,f.closed);assertEquals(1,f.modelClosed);assertEquals(1,f.resumed);assertTrue(f.effects.indexOf("capture-close")<f.effects.indexOf("quiet-closed"));}
 @Test public void cancelledQuietCallbackCannotStartCaptureOrRepeatAdmission(){Fake f=new Fake();SpeakRuntime r=make(f);r.start();r.cancel();f.ready.run();f.run();assertEquals(0,f.models);assertEquals(0,f.opened);assertEquals(1,f.resumed);assertFalse(r.start());assertEquals(SpeakRuntime.State.CANCELLED,r.state);}
 @Test public void deadlineWithoutQuietSupportsFallbackAndNeverStartsMicrophone(){Fake f=new Fake();SpeakRuntime r=make(f);r.start();f.time=15000;r.tick();f.ready.run();f.run();assertTrue(r.released());assertEquals(0,f.opened);assertEquals(1,f.resumed);assertEquals(SpeakRuntime.State.ERROR,r.state);}
 @Test public void permissionRevokedDuringInferenceClosesAndCannotAcceptSpeech(){Fake f=new Fake();SpeakRuntime r=make(f);r.start();f.duringInfer=()->f.allowed=false;f.ready.run();f.run();assertEquals(SpeakRuntime.State.ERROR,r.state);assertEquals(1,f.closed);assertEquals(1,f.resumed);}
 @Test public void ownerReplacementDuringInferenceCannotCompleteOrResumeUnrelatedSound(){Fake f=new Fake();SpeakRuntime r=make(f);r.start();f.duringInfer=()->f.live=false;f.ready.run();f.run();assertNotEquals(SpeakRuntime.State.DONE,r.state);assertEquals(1,f.closed);assertEquals(0,f.resumed);}
 @Test public void explicitCancelDuringInferenceStillWaitsForConfirmedCleanup(){Fake f=new Fake();SpeakRuntime r=make(f);r.start();f.duringInfer=r::cancel;f.ready.run();f.run();assertEquals(SpeakRuntime.State.CANCELLED,r.state);assertEquals(1,f.closed);assertEquals(1,f.resumed);}
 @Test public void failedNativeCloseBlocksResultAndSoundUntilExplicitCleanupRetry(){Fake f=new Fake();f.closeFailed=true;SpeakRuntime r=make(f);r.start();f.ready.run();f.run();assertEquals(SpeakRuntime.State.BLOCKED,r.state);assertFalse(r.released());assertEquals(0,f.resumed);r.cancel();assertEquals(SpeakRuntime.State.BLOCKED,r.state);f.closeFailed=false;r.retryCleanup();assertEquals(0,f.resumed);f.run();assertTrue(r.released());assertEquals(SpeakRuntime.State.ERROR,r.state);assertEquals(1,f.resumed);}
 @Test public void zeroSamplesNeverBecomeSpeechAndStopAtBudget(){Fake f=new Fake();f.zero=true;SpeakRuntime r=make(f);r.start();f.ready.run();f.run();assertNotEquals(SpeakRuntime.State.DONE,r.state);assertEquals(0,r.accepted);assertEquals(1,f.closed);assertEquals(1,f.resumed);assertTrue(f.time>=15000);}
 @Test public void unavailableQuietBarrierHasNoModelOrCapture(){Fake f=new Fake();f.failQuiet=true;SpeakRuntime r=make(f);r.start();assertEquals(SpeakRuntime.State.ERROR,r.state);assertEquals(0,f.opened);assertEquals(0,f.models);}
 @Test public void modelFailureBeforeCaptureResumesOnlyOwnedSound(){Fake f=new Fake();f.modelFailed=true;SpeakRuntime r=make(f);r.start();f.ready.run();f.run();assertEquals(SpeakRuntime.State.ERROR,r.state);assertEquals(0,f.opened);assertEquals(1,f.resumed);}
 @Test public void sharedMicrophoneTokenNeverReleasesNewOwner(){MicrophoneLease a=MicrophoneLease.acquire("test-a");assertNotNull(a);try{assertNull(MicrophoneLease.acquire("test-b"));a.released();MicrophoneLease b=MicrophoneLease.acquire("test-b");assertNotNull(b);try{a.released();assertTrue(b.current());assertTrue(MicrophoneLease.occupied());}finally{b.released();}}finally{a.released();}assertFalse(MicrophoneLease.occupied());}
 @Test public void resultProofRejectsWrongRequestUnitAndReplacementAndConsumesOnce(){SpeakProof p=new SpeakProof("run",2,"nonce");assertFalse(p.consume("run",2,"wrong","run",2,true,true));assertTrue(p.consume("run",2,"nonce","run",2,true,true));assertFalse(p.consume("run",2,"nonce","run",2,true,true));SpeakProof stale=new SpeakProof("old",2,"nonce");assertFalse(stale.consume("old",2,"nonce","new",2,true,true));assertFalse(stale.consume("old",2,"nonce","old",2,true,true));assertFalse(new SpeakProof("run",2,"n").consume("run",2,"n","run",2,false,true));}
 @Test public void speakTaskIsOneUnitAndNeverLegacyAutoselection(){assertEquals(1,new ChallengeRoutine.Task("Speak",1).units());assertThrows(IllegalArgumentException.class,()->new ChallengeRoutine.Task("Speak",2));assertEquals("Math",ChallengeRoutine.legacy("Speak",3).tasks.get(0).type);}
}
